return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Polish','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:32+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'pl_PL','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" zapisano.','"%1$s" created. %2$d template updated.'=>'"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '','"%s" created.'=>'"%s" został utworzony.','%d language not yet linked'=>'%d język jeszcze nie powiązany' . "\0" . '%d języków jeszcze nie powiązanych' . "\0" . '','%d link updated.'=>'%d link zaktualizowany.' . "\0" . '%d linków zaktualizowanych.' . "\0" . '','%d locale pack installed.'=>'Zainstalowano %d pakiet lokalizacyjny.' . "\0" . 'Zainstalowano %d pakietów lokalizacyjnych.' . "\0" . '','%d navigation reference updated.'=>'%d odwołanie do nawigacji zaktualizowane.' . "\0" . '%d odwołań do nawigacji zaktualizowanych.' . "\0" . '','%d part reference updated.'=>'%d odwołanie do części zaktualizowane.' . "\0" . '%d odwołań do części zaktualizowanych.' . "\0" . '','%s Archive'=>'%s Archiwum','(avg %.1f hits/block)'=>'(średnio %.1f trafień/blok)','(avg %.1f hits/entry)'=>'(średnio %.1f trafień/pozycję)','(disabled)'=>'wyłączone','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} nie miało wymienialnych linków — ponowne skanowanie w celu sprawdzenia)','.txt file(s) in the directory'=>'.txt plik(i) w katalogu','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizowanych szablonów z motywu „%2$s” jest zachowanych w bazie danych, ale są obecnie nieaktywne. Ponownie staną się aktywne, jeśli ponownie aktywujesz ten motyw. Aby przenieść swoje tłumaczenia do nowego motywu, wygeneruj je ponownie za pomocą <strong>Ustawienia → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatycznie naprawialnych linków','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> linków wymagających ręcznej weryfikacji','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> nieaktualna(e) ścieżka(e)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problem(y) z szablonem','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akceptuje tylko skompilowane pliki .mo. Nazwa pliku musi mieć wzór {textdomain}-{locale}.mo. Przesłanie pliku o tej samej nazwie co istniejący spowoduje jego zastąpienie.','Action'=>'Akcja','Actions'=>'Działania','active'=>'aktywne','Active Languages'=>'Aktywne języki','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktywne języki: dodaj każdy język, który chcesz obsługiwać. Każdy język otrzymuje prefiks URL lub subdomenę oraz tag hreflang w sekcji &lt;head&gt; strony.','Active Provider'=>'Aktywny dostawca','Add entry'=>'Dodaj wpis','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Dodaj instrukcje, aby ulepszyć szkic — np. skróć go, dodaj sekcję podsumowania, użyj bardziej formalnego rejestru, dodaj blok FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Dodaj instrukcje, aby poprawić szkic — np. skróć go, dodaj sekcję podsumowania, użyj bardziej formalnego rejestru…','Add new entry'=>'Dodaj nowy wpis','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Dodaj jeden termin na wiersz. Zarówno termin źródłowy, jak i docelowy są wymagane. Para języków określa, do których zadań tłumaczeniowych obowiązuje ograniczenie.','Adds a link to the home page so visitors can browse in their language.'=>'Dodaje link do strony głównej, aby odwiedzający mogli przeglądać w swoim języku.','Administrators only (manage_options)'=>'Tylko administratorzy (zarządzaj_opcjami)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Po zmianie głównego języka, odśwież permalink (sekcja poniżej), aby zaktualizować trasowanie URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Po zmianie ustawień struktury URL (prefiks ścieżki ↔ subdomena), zawsze odwiedź Ustawienia → Bezpośrednie odnośniki i kliknij Zapisz zmiany, aby odświeżyć reguły przekierowań.','AI Behaviour Preset'=>'Predefiniowany zachowanie AI','AI cache cleared. %d entry was removed.'=>'Pamięć podręczna AI wyczyszczona. %d wpis został usunięty.' . "\0" . 'Pamięć podręczna AI wyczyszczona. %d wpisów zostało usuniętych.' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Pamięć podręczna AI: lista zapisanych odpowiedzi AI z licznikami trafień. Wyczyść całą pamięć podręczną lub wpisy pojedynczego posta. Użyj "Wyczyść" przed testowaniem zmiany tłumaczenia — zapisane wyniki są zwracane nawet po zmianie presetów lub modelu AI, dopóki wpis w pamięci podręcznej nie zostanie usunięty.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Funkcje AI są opcjonalne. Routing językowy, hreflang, przełącznik języków i system grup tłumaczeń działają bez skonfigurowanego dostawcy.','AI Limits & Security'=>'Limity i bezpieczeństwo AI','AI provider returned an empty response.'=>'Dostawca AI zwrócił pustą odpowiedź.','AI Usage'=>'Użycie AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Celuj w 120–160 znaków. Pozostaw puste, aby użyć zapasowego fragmentu.','All time'=>'Wszystko','Allow editors to lock individual blocks'=>'Zezwól redaktorom na blokowanie poszczególnych bloków','Allow Gutenberg template-editing mode on post screens'=>'Zezwól na tryb edycji szablonów Gutenberga na ekranach wpisów','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Usuń również przypisania językowe, relacje tłumaczeń, meta opisy, glosariusz i pamięć tłumaczeń podczas odinstalowania wtyczki.','Also generate meta description'=>'Również wygeneruj metaopis','Alternative (server-side):'=>'Alternatywnie (po stronie serwera):','An unknown error occurred.'=>'Wystąpił nieznany błąd.','and'=>'i','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'dowolny','API calls saved by cache'=>'Wywołania API zapisane w pamięci podręcznej','API Key'=>'Klucz API','API Keys'=>'Klucze API','API Keys Tab'=>'Zakładka kluczy API','API Response Cache'=>'Pamięć podręczna odpowiedzi API','Applied ✓'=>'Zastosowano ✓','Apply failed — please try again.'=>'Nie udało się zastosować — spróbuj ponownie.','Apply to Block'=>'Zastosuj do bloku','Apply to Editor'=>'Zastosuj do Edytora','Apply to Footnote'=>'Zastosuj do przypisu','Apply to Meta Description'=>'Zastosuj do Opisu Meta','Apply translation'=>'Zastosuj tłumaczenie','Applying…'=>'Zastosowanie…','Approximate size'=>'Przybliżony rozmiar','Archive'=>'Archiwum','Archive: %s'=>'Archiwum: %s','Authors and above (edit_published_posts)'=>'Autorzy i wyżej (edytuj_opublikowane_posty)','Behavior'=>'Zachowanie','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Zachowanie: wybierz preset AI (Literal, Balanced, Creative), dodaj instrukcje niestandardowe dla całej witryny, włącz lub wyłącz automatyczne tłumaczenie po zapisaniu posta oraz skonfiguruj Pamięć tłumaczeń.','Block Content'=>'Zawartość bloku','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Wyświetla uprzejme powiadomienie, gdy obecna strona jest wyświetlana w jej języku źródłowym, ponieważ nie istnieje tłumaczenie dla języka odwiedzającego. Napędzane sygnałem LINGUAFORGE_LANG_FALLBACK_ACTIVE routera Lingua Forge — nie emituje nic, gdy istnieje tłumaczenie dla żądanej lokalizacji.','Block Editor'=>'Edytor bloków','block keywordfallback'=>'zapas','block keywordi18n'=>'i18n','block keywordlanguage'=>'język','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'tłumaczenie','Block locking'=>'Blokada','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Wzory bloków zarejestrowane dla niestandardowych typów postów. Użyj przycisku Tłumacz, aby wygenerować wersję językową. Tłumaczona zawartość jest zapisywana tutaj i może być skopiowana do dowolnego posta CPT z edytora bloków lub użyta jako punkt wyjścia dla Wzoru synchronizowanego (Blok wielokrotnego użytku).','block titleMissing Translation Notice'=>'Powiadomienie o braku tłumaczenia','Block translation reuses'=>'Ponowne użycie tłumaczeń bloków','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Pamięć podręczna tłumaczeń na poziomie bloków, współdzielona między postami. Po włączeniu, identyczne bloki (ta sama składnia, para języków i glosariusz) są serwowane z pamięci zamiast ponownego wywoływania AI. Konfiguruj w Ustawienia → Zachowanie.','Browser language redirect'=>'Przekierowanie języka przeglądarki','Built-in preset instructions:'=>'Wbudowane instrukcje presetów:','Bulletize (•-prefixed)'=>'Użyj punktów (•-prefiks)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Buforuj tłumaczone odpowiedniki na poziomie bloków, aby wielokrotne treści (wspólne stopki, paski boczne, akordeony, sekcje prawne z dużą ilością boilerplate\'u) nie wymagały wywołania API za każdym razem. Gdy funkcja jest włączona, przepływ tłumaczenia analizuje każdy wpis na bloki, sprawdza je w pamięci podręcznej i wysyła tylko niepamiętane bloki do AI w jednym zgrupowanym żądaniu. Edycje słownika i zmiany presetów zgodności automatycznie unieważniają odpowiednie tłumaczenia w pamięci podręcznej. Wyświetl statystyki i wyczyść pamięć podręczną w sekcji Utrzymanie.','cached'=>'pamięć podręczna','Cached API responses'=>'Zapisane odpowiedzi API','Cached block translations'=>'Zapisane tłumaczenia bloków','Cancel'=>'Anuluj','Cannot determine target language from slug.'=>'Nie można określić docelowego języka na podstawie slug.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Ogranicz ilość korzystania z AI na stronie i ogranicz role użytkowników, które mogą wywołać płatne wywołania AI. Nakłada się na limit na poziomie użytkownika (30 żądań / minuta, na stałe), który już chroni przed niekontrolowanymi pętlami pojedynczego użytkownika.','chars'=>'znaki','Chunk translated'=>'Fragment przetłumaczony','Chunk translated to:'=>'Fragment przetłumaczony na:','Clear'=>'Wyczyść','Clear All'=>'Wyczyść wszystko','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Czy wyczyścić wszystkie zapisane wyniki AI? Przyszłe żądania będą wywoływać nowe wywołania API, aż do odbudowania pamięci podręcznej.','Clear API Response Cache'=>'Wyczyść pamięć podręczną odpowiedzi API','Clear Debug Files'=>'Wyczyść pliki debugowania','Clear hints'=>'Wyczyść podpowiedzi','Clear input'=>'Wyczyść wejście','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Wyczyścić całą pamięć tłumaczeń? Przyszłe tłumaczenia odbudują pamięć podręczną podczas ich wykonywania.','Clear Translation Memory'=>'Wyczyść pamięć tłumaczeń','Close'=>'Zamknij','Close language panel'=>'Zamknij panel językowy','Close popover'=>'Zamknij podpowiedź','Compliance Preset'=>'Predefiniowany ustawienie zgodności','Content generated'=>'Treść wygenerowana','Content Generator'=>'Generator treści','Content ready'=>'Treść gotowa','Contributors and above — default (edit_posts)'=>'Współtwórcy i wyżej — domyślnie (edytuj_posty)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontroluj, ile treści jest wysyłanych do AI i jak duża może być odpowiedź. Pozostaw puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Zwiększ te wartości, jeśli duże strony są obcinane; zmniejsz je, aby obniżyć koszty API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Kontroluje budżet tokenów i limity wejścia dla funkcji Generatora treści AI. Pozostaw puste, aby użyć wbudowanych domyślnych ustawień.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kontroluje, co się dzieje, gdy administrator usuwa wtyczkę z Plugins → Installed Plugins → Delete. Ustawienia wtyczki i pamięć podręczna AI są zawsze usuwane. Przydziały językowe i relacje tłumaczeń są domyślnie zachowywane, więc przypadkowe odinstalowanie lub reinstalacja mogą kontynuować tam, gdzie zostały przerwane.','Conversational'=>'Konwersacyjne','Copied ✓'=>'Skopiowano ✓','Copy'=>'Kopiuj','Copy markup'=>'Kopiuj kod','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Skopiuj wynik i wklej tam, gdzie jest to potrzebne (np. bezpośrednio do pola przypisu).','Copy to safe storage'=>'Kopiuj do bezpiecznej pamięci','Could not add entry: source term and target term are required.'=>'Nie można dodać wpisu: wymagany jest termin źródłowy i termin docelowy.','Could not copy the file. Check that the uploads folder is writable.'=>'Nie można skopiować pliku. Sprawdź, czy folder uploads jest zapisywalny.','Could not instantiate the provider.'=>'Nie można utworzyć instancji dostawcy.','Could not save the file. Check that the uploads folder is writable.'=>'Nie można zapisać pliku. Sprawdź, czy folder uploads jest zapisywalny.','Could not save the glossary entry.'=>'Nie można zapisać wpisu słownika.','CPT Block Patterns'=>'Wzory bloków CPT','Create'=>'Utwórz','Create missing'=>'Utwórz brakujące','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Tworzenie tłumaczeń dla typu posta "%s" wymaga aktywnej integracji. Upewnij się, że wymagana integracja jest zainstalowana i aktywna.','Creating…'=>'Tworzenie…','Creative / Marketing'=>'Kreatywny / Marketing','Creative / Marketing instructions'=>'Instrukcje kreatywne / marketingowe','Current content (will be overwritten)'=>'Aktualna treść (zostanie nadpisana)','Current title'=>'Aktualny tytuł','Current: {current}'=>'Aktualne: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Obecnie dziedziczone z constanty %s. Wybranie wartości tutaj nadpisze to.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Obecnie pomijane dla wpisów korzystających z atrybutów blok-comment (np. wp:details, pola podsumowania) — przechodzą do istniejącej ścieżki tłumaczenia wywołania pojedynczego.','Currently:'=>'Obecnie:','Custom'=>'Niestandardowe','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Dzienne limity AI osiągnięte (%1$d żądań). Reset o %2$s UTC.','Daily request limit'=>'Dzienny limit żądań','Debug Files'=>'Pliki debugowania','Debug files cleared. %d file was removed.'=>'Pliki debugowania wyczyszczone. Usunięto %d plik.' . "\0" . 'Pliki debugowania wyczyszczone. Usunięto %d plików.' . "\0" . '','Debug logging'=>'Logowanie debugowania','Debug logging disabled.'=>'Logowanie debugowania wyłączone.','Debug logging enabled.'=>'Logowanie debugowania włączone.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debugowanie: włącz dziennik debugowania, aby rejestrować zapytania AI i odpowiedzi API do lokalnego pliku. Wyłącz po rozwiązaniu problemów — tryb debugowania zapisuje plik przy każdym żądaniu AI.','Delete'=>'Usuń','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Czy chcesz usunąć wszystkie pliki .txt w katalogu debugowania? Sam katalog pozostanie, aby przyszłe zapisy debugowania mogły się tam trafiać.','Delete all files for this override (both .mo and .po)?'=>'Usunąć wszystkie pliki dla tego nadpisania (zarówno .mo, jak i .po)?','Delete content data on uninstall'=>'Usuń dane zawartości podczas odinstalowania','Delete this glossary entry?'=>'Czy chcesz usunąć ten wpis słownika?','Describe what to write — topic, key points, structure…'=>'Opisz, co napisać — temat, kluczowe punkty, struktura…','Directory'=>'Katalog','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Wyłącz podczas dostrajania promptów lub gdy chcesz, aby każde żądanie dotarło do dostawcy AI. Wyłączenie nie usuwa zapisanych wpisów — ponowne włączenie je przywraca. Natychmiastowe zwiększenie wydatków na API na obciążonych stronach jest spodziewane przy wyłączeniu.','Display'=>'Wyświetlacz','Displays the Lingua Forge language switcher.'=>'Wyświetla przełącznik języków Lingua Forge.','Documentation'=>'Dokumentacja','Done'=>'Gotowe','Done — {done} of {total} post(s) fixed.'=>'Zakończono — naprawiono {done} z {total} postów.','Down'=>'Dół','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pobierz i zainstaluj pakiet językowy WordPress bezpośrednio z WordPress.org. Po instalacji lokalizacja będzie dostępna do routingu URL i workflow tłumaczeń AI. Lista dostępnych języków jest pobierana na żądanie — kliknij przycisk poniżej, aby ją załadować.','Dropdown direction'=>'Kierunek rozwijanego menu','Editors and above (edit_others_posts)'=>'Redaktorzy i wyżej (edytuj_inne_posty)','Enable API response caching'=>'Włącz buforowanie odpowiedzi API','Enable block-level translation cache reuse across posts'=>'Włącz ponowne użycie pamięci podręcznej tłumaczeń na poziomie bloków między wpisami','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Wprowadź swój klucz API dla co najmniej jednego dostawcy AI. Klucze są szyfrowane w spoczynku za pomocą AES-256-GCM z tajnym kluczem specyficznym dla witryny (LINGUAFORGE_SECRET). Nie udostępniaj eksportów bazy danych bez najpierw rotacji sekretu.','environment variable'=>'zmienna środowiskowa','Error'=>'Błąd','Expand'=>'Rozszerz','Expected: {expected}'=>'Oczekiwane: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Dodatkowe wskazówki — ton, styl, ograniczenia, grupa docelowa…','Extra guidance — tone, style, constraints…'=>'Dodatkowe wskazówki — ton, styl, ograniczenia…','Failed. Please try again.'=>'Nie powiodło się. Spróbuj ponownie.','Feature'=>'Funkcja','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funkcje są pogrupowane w dwie warstwy. Wprowadź dokładny identyfikator modelu dla każdej warstwy i dostawcy. Pozostaw pole puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Tylko modele aktywnego dostawcy są wywoływane podczas działania — skonfiguruj pozostałe wcześniej, jeśli planujesz zmianę.','File copied to safe storage successfully.'=>'Plik skopiowany do bezpiecznej pamięci pomyślnie.','Files'=>'Pliki','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Pliki trafiają do poniższego katalogu. Przydatne do diagnozowania problemów z tłumaczeniem — wyłącz po uzyskaniu potrzebnych danych, aby pliki się nie gromadziły. Możesz też wymusić to z wp-config.php za pomocą `define( \'LINGUAFORGE_AI_DEBUG\', true );`, co nadpisuje ten przełącznik.','Filter'=>'Filtr','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtruj za pomocą linguaforge_debug_dir, aby przekierować wyjście debugowania do niepublicznej lokalizacji.','Fix'=>'Napraw','Fix All'=>'Napraw wszystko','Fix all links'=>'Napraw wszystkie linki','Fix all parts'=>'Napraw wszystkie części','Fix Links'=>'Napraw linki','Fix Nav'=>'Napraw nawigację','Fix Parts'=>'Napraw części','Fix Template'=>'Napraw szablon','Fixing {n} / {total}…'=>'Naprawa {n} / {total}…','Fixing…'=>'Naprawianie…','Flush Permalink Rules'=>'Wyczyść reguły permalinków','Flush Permalinks'=>'Wyczyść permalinki','Footnote Content'=>'Treść przypisu','footnote(s) translated — applied together with content.'=>'Przetłumaczono przypis(y) — zastosowano razem z treścią.','Footnotes'=>'Przypisy','Footnotes payload (advanced)'=>'Dane odnośników (zaawansowane)','Forbidden'=>'Zabronione','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone wyłączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone włączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Znaleziono {parts} wśród <strong>{total}</strong> z <strong>{scanned}</strong> zeskanowanych postów dla <strong>{lang}</strong>.','From'=>'Od','Front Page'=>'Strona główna','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Lokalizacja FSE: tworzenie szkieletu, tłumaczenie i naprawa linków w szablonach i częściach szablonów Full Site Editing bezpośrednio z tego zakładki.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Szablony FSE utworzone z aktywnego motywu. Utwórz, a następnie dostosuj w Edytorze witryny.','Full Article'=>'Pełny artykuł','Full post'=>'Pełny post','General'=>'Ogólne','Generate'=>'Generuj','Generate Content'=>'Generuj treść','Generate content…'=>'Generuj treść…','Generate Excerpt'=>'Wygeneruj fragment','Generate Meta Description'=>'Wygeneruj metaopis','Generated Content'=>'Wygenerowana treść','Generated meta description'=>'Wygenerowany meta opis','Generating…'=>'Tworzenie…','Generation failed.'=>'Niepowodzenie generowania.','Getting started'=>'Rozpoczęcie','Global AI preset'=>'Globalny preset AI','Global default (%s)'=>'Domyślny globalny (%s)','Glossary'=>'Słownik','Glossary entry added.'=>'Wpis słownika dodany.','Glossary entry removed.'=>'Wpis słownika usunięty.','Glossary Tab'=>'Zakładka słownika','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Ukryj','Hints'=>'Wskazówki','Home link text'=>'Tekst linku do strony głównej','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jak powinna wyglądać w tłumaczeniu. Wpisz tę samą wartość co termin źródłowy, aby nakazać AI zachować ją dosłownie.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikona + etykieta','Icon only'=>'Tylko ikona','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jeśli zaznaczysz, odinstalowanie wtyczki trwale usunie wszystkie przypisania językowe, relacje tłumaczeń, meta opisy, ustawienia na stronie, glosariusz AI i pamięć tłumaczeń dla każdego posta na tej stronie. Nie można tego cofnąć. Odznacz, jeśli chcesz całkowicie usunąć obsługę wielojęzyczności ze strony.','Improve writing'=>'Popraw pisanie','Informative'=>'Informacyjne','Input tokens'=>'Tokeny wejściowe','Install'=>'Zainstaluj','Install a Language'=>'Zainstaluj język','Installing…'=>'Instalacja…','Instructions (optional)'=>'Instrukcje (opcjonalnie)','Instructions / key points'=>'Instrukcje / kluczowe punkty','Integration API'=>'API integracji','Internal Link Fixer'=>'Naprawiacz linków wewnętrznych','Introduction only'=>'Tylko wprowadzenie','Invalid file reference.'=>'Nieprawidłowe odniesienie do pliku.','Invalid filename.'=>'Nieprawidłowa nazwa pliku.','Invalid language.'=>'Nieprawidłowy język.','Invalid locale code.'=>'Nieprawidłowy kod lokalizacji.','Invalid or primary language.'=>'Nieprawidłowy lub główny język.','Invalid post type.'=>'Nieprawidłowy typ wpisu.','Invalid template part.'=>'Nieprawidłowa część szablonu.','Invalid template type.'=>'Nieprawidłowy typ szablonu.','Key points, ideas, or structure to build from…'=>'Kluczowe punkty, pomysły lub struktura do zbudowania...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Klucze są szyfrowane za pomocą AES-256-CBC przed zapisaniem w bazie danych WordPress. Sekret szyfrowania pochodzi z Twoich soli uwierzytelniania WordPress (wp-config.php), więc klucze w formacie tekstowym nigdy nie trafiają do bazy danych.','Language'=>'Język','Language %s installed successfully.'=>'Język %s został pomyślnie zainstalowany.','Language (optional)'=>'Język (opcjonalnie)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Instalacja języków jest wyłączona na tym serwerze (ustawiono DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Instalacja języków jest wyłączona na tym serwerze. Stała DISALLOW_FILE_MODS jest ustawiona w wp-config.php. Zainstaluj pakiety językowe ręcznie za pomocą WP-CLI: wp language core install de_DE','Language label'=>'Etykieta języka','Language Overrides'=>'Nadpisywanie języka','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Nadpisywanie języków: zarządzaj niestandardowymi plikami .po/.mo dla tekstów interfejsu Lingua Forge. Używaj tego zamiast bezpośredniej edycji plików wtyczki — nadpisy zachowują się po aktualizacjach.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Niepowodzenie instalacji pakietu językowego. Język może być już zainstalowany, kod lokalizacji może być niepoprawny lub serwer może blokować zapisy plików.','Language Setup'=>'Ustawienia języka','Language Switcher'=>'Przełącznik języków','Language switcher'=>'Przełącznik języków','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Kopie części szablonów tematu specyficzne dla języka. Po utworzeniu, szablony są aktualizowane, aby odwoływały się do części specyficznej dla języka.','Language:'=>'Język:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Języki obecnie znane routerowi (pochodzące z zainstalowanych pakietów lokalizacyjnych WordPress oraz główny język). Zainstaluj dodatkowe pakiety językowe w poniższej sekcji, aby udostępnić więcej języków do routingu i tłumaczeń.','Last 30 days'=>'Ostatnie 30 dni','Last 7 days'=>'Ostatnie 7 dni','Lead paragraph (≤60 w)'=>'Wstępny akapit (≤60 sł)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Pozostaw pole modelu puste, aby użyć wbudowanego domyślnego dla tego poziomu. Tekst zastępczy pokazuje, który model będzie używany.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Pozostaw puste dla nazw marek i terminów niezależnych od języka, które mają być egzekwowane bez względu na język tłumaczenia.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Pozostaw puste, aby zastosować tę pozycję do wszystkich języków docelowych — idealne dla nazw marek, skrótów i terminów, które muszą być zachowane dosłownie w każdym tłumaczeniu.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Pozostaw puste, aby zachować istniejący klucz. Wprowadź nową wartość, aby go zastąpić.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Pozostaw puste, aby użyć wbudowanego domyślnego ustawienia. Wyczyszczenie zapisanej nadpisanej wartości przywraca domyślną wartość przy następnym zapisie.','Legal / Compliance'=>'Prawny / Zgodność','Legal / Compliance instructions'=>'Instrukcje prawne / zgodności','Light'=>'Lekki','Light (default — fast and cost-effective)'=>'Lekki (domyślny — szybki i opłacalny)','Light (fast and cost-effective — Haiku / Flash)'=>'Lekki (szybki i ekonomiczny — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Lekki: używany do meta opisów i generowania fragmentów — szybki, niskokosztowy.','Limit results to pages in the given Lingua Forge language code.'=>'Ogranicz wyniki do stron w podanym kodzie języka Lingua Forge.','Limits'=>'Limity','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge dodaje wielojęzyczne routingi, tłumaczenia oparte na AI, tagi hreflang SEO i przełącznik języków do Twojej witryny WordPress.','Lingua Forge AI Tools'=>'Narzędzia Lingua Forge AI','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge domyślnie ogranicza dwie funkcje Gutenberga, aby zachować spójne zachowanie redakcyjne w różnych językach. Zaznacz tutaj, gdy potrzebujesz pełnych możliwości Gutenberga / FSE.','Lingua Forge Settings'=>'Ustawienia Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge używa dwóch niezależnych warstw pamięci podręcznej, aby uniknąć zbędnych wywołań API AI. Użyj poniższych zakładek, aby sprawdzić i zarządzać każdą z nich.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge używa dwóch poziomów modeli na dostawcę:','Lingua Forge — Quick Translate'=>'Lingua Forge — Szybkie tłumaczenie','Lingua Forge — Settings'=>'Lingua Forge — Ustawienia','link(s)'=>'link(i)','Links'=>'Linki','Load available languages'=>'Załaduj dostępne języki','Loading…'=>'Wczytywanie…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate przechowuje własne tłumaczenia w wp-content/languages/loco/ — lokalizacji, którą można cicho wyczyścić podczas aktualizacji WP, reinstalacji wtyczki lub usunięcia Loco Translate. Kopiowanie plików tutaj przenosi je do katalogu Lingua Forge i18n-overrides, który przetrwa te wszystkie zdarzenia i jest automatycznie ładowany przy każdym żądaniu.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiuj do bezpiecznej pamięci','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Najniższa zdolność WordPress do wywoływania funkcji AI. Ograniczenie tego na stronach z wieloma autorami zapobiega uruchamianiu płatnych wywołań AI przez Współtwórców lub konta próbne. Nadpisz per funkcja za pomocą filtra linguaforge_required_capability.','Maintenance'=>'Utrzymanie','Maintenance Tab'=>'Zakładka konserwacji','Make casual'=>'Uczyń nieformalnym','Make concise'=>'Uczyń zwięzłym','Make formal'=>'Uczyń formalnym','Mark citations needed'=>'Oznacz cytaty jako potrzebne','Max context characters'=>'Maksymalny kontekst','Max hints characters'=>'Maksymalna liczba znaków wskazówek','Max input characters'=>'Maksymalna liczba znaków wejściowych','Max output tokens'=>'Maksymalna liczba tokenów wyjściowych','Maximum characters accepted from the input field. Default: 8 000.'=>'Maksymalna liczba znaków akceptowanych z pola wejściowego. Domyślnie: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maksymalna liczba znaków istniejącej treści posta przekazywanej do AI jako kontekst startowy, gdy nie podano wskazówek. Domyślnie: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Maksymalna liczba znaków odczytanych z pola wskazówek. Domyślnie: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maksymalna liczba znaków treści posta przekazywanej do AI. 0 oznacza brak limitu — pełna treść jest zawsze wysyłana (zalecane). Ustaw wartość różną od zera tylko wtedy, gdy twój dostawca ma ograniczone okno kontekstowe. Ostrzeżenie jest zapisywane w dzienniku błędów PHP za każdym razem, gdy treść jest przycinana.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować w jednej odpowiedzi tłumaczeniowej. Jeśli tłumaczenie jest cicho obcinane na końcu, zwiększ tę wartość. Domyślnie: 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maksymalna liczba tokenów, które AI może wygenerować na jedno uruchomienie. Zwiększ, jeśli pełne artykuły są obcinane. Domyślnie: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować na szybkie tłumaczenie. Domyślnie: 2000.','Meta Description'=>'Meta opis','Meta Description, Excerpt Generator'=>'Meta Description, Generator fragmentów','Minimum role'=>'Minimalna rola','Missing pattern name or language.'=>'Brak nazwy wzoru lub języka.','Mode'=>'Tryb','Model'=>'Model','Model tier'=>'Poziom modelu','Models'=>'Modele','Models Tab (General)'=>'Zakładka modeli (Ogólne)','Most recent cached block'=>'Ostatni zapisany blok','Most recent cached response'=>'Ostatnia zapisana odpowiedź','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Wielojęzyczne routingi, meta tagi SEO i narzędzia AI do treści dla WordPress. Łączy wykrywanie języka, routing URL, hreflang, opisy meta oraz funkcje AI do wycinków, meta i tłumaczeń.','Name displayed in this language. Leave empty to use the source name.'=>'Nazwa wyświetlana w tym języku. Pozostaw puste, aby użyć nazwy źródłowej.','Navigation'=>'Nawigacja','Navigation has no content to translate.'=>'Nawigacja nie zawiera treści do tłumaczenia.','Navigation not found.'=>'Nawigacja nie znaleziona.','Navigation posts are translated via the Router tab, not this button.'=>'Posty nawigacji są tłumaczone przez zakładkę Router, a nie tym przyciskiem.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Tłumaczenie nawigacji wymaga aktywnego dostawcy AI. Skonfiguruj klucz API w zakładce Klucze API.','Navigations'=>'Nawigacje','Network error — could not reach the WordPress AJAX endpoint.'=>'Błąd sieci — nie można nawiązać kontaktu z punktem końcowym AJAX WordPress.','No %s version found in this translation group.'=>'Nie znaleziono wersji %s w tej grupie tłumaczeń.','No AI provider configured.'=>'Nie skonfigurowano dostawcy AI.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nie zarejestrowano użycia AI w wybranym oknie (%s). Wybierz szerszy zakres powyżej.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Jeszcze nie zarejestrowano użycia AI. Gdy edytor wykona tłumaczenie, wygeneruje opis meta lub skorzysta z innej funkcji AI, sumy pojawią się tutaj.','No API key configured for this provider.'=>'Dla tego dostawcy nie skonfigurowano klucza API.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Brak wbudowanych instrukcji — każda funkcja AI korzysta z własnych dostrojonych domyślnych ustawień. Wypełnij poniższe pole Instrukcje niestandardowe, aby dodać własne zasady dla całej witryny.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Jeszcze nie znaleziono własnych plików Loco Translate. Pojawią się tutaj po zapisaniu tłumaczenia w Loco Translate.','No file was selected.'=>'Nie wybrano pliku.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Brak wpisów słownika pasujących do obecnego filtra. Wyczyść filtr, aby zobaczyć wszystkie wpisy, lub dodaj nowy wpis poniżej.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Brak jeszcze wpisów słownika. Dodaj jeden poniżej, aby zacząć egzekwować terminologię w tłumaczeniach.','No internal links found to update.'=>'Nie znaleziono wewnętrznych linków do aktualizacji.','No language-specific template parts found to map.'=>'Nie znaleziono części szablonu specyficznych dla języka do mapowania.','No navigation references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do nawigacji.','No override files uploaded yet.'=>'Jeszcze nie przesłano żadnych plików nadpisujących.','No response from provider — check the error log for details.'=>'Brak odpowiedzi od dostawcy — sprawdź dziennik błędów po szczegóły.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Brak skonfigurowanych języków drugorzędnych. Zainstaluj pakiet językowy powyżej, aby włączyć szablony.','No source content found to translate.'=>'Nie znaleziono treści źródłowej do tłumaczenia.','No source page linked yet.'=>'Jeszcze nie powiązano strony źródłowej.','No template part references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do części szablonu.','No {lang} translation registered (TRID missing)'=>'Nie zarejestrowano tłumaczenia {lang} (brak TRID)','Notes'=>'Uwagi','Notice message'=>'Wiadomość powiadomienia','Notice settings'=>'Ustawienia powiadomień','Oldest cached block'=>'Najstarszy zapisany blok','Oldest cached response'=>'Najstarsza zapisana odpowiedź','Only .mo files are accepted.'=>'Akceptowane są tylko pliki .mo.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Opcjonalny kontekst dla redaktorów (np. "ASIC = układ scalony specjalistyczny; zachować w języku angielskim w kontekstach technicznych").','Output'=>'Wynik','Output tokens'=>'Tokeny wyjściowe','overridden'=>'nadpisane','Override file deleted.'=>'Plik nadpisania został usunięty.','Override file uploaded successfully.'=>'Nadpisanie pliku zostało pomyślnie przesłane.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Wszystkie inne funkcje zawsze korzystają z globalnego preset.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Instrukcje niestandardowe dla całej witryny (Ustawienia → Zachowanie) są zawsze dodawane do każdego żądania, niezależnie od tego wyboru.','Overview'=>'Przegląd','Page'=>'Strona','Part'=>'Część','Paste a footnote, sentence, or any snippet here…'=>'Wklej tutaj przypis, zdanie lub dowolny fragment…','Paste text, or select text in the editor first…'=>'Wklej tekst lub najpierw zaznacz tekst w edytorze…','Paste text, or select text on the page first…'=>'Wklej tekst lub najpierw zaznacz tekst na stronie…','Paste your API key…'=>'Wklej swój klucz API…','Path prefix — example.com/de/'=>'Przedrostek ścieżki — example.com/pl/ lub example.com/de/ (w zależności od języka)','Pattern'=>'Wzór','Pattern has no content to translate.'=>'Wzór nie ma treści do tłumaczenia.','Pattern not found.'=>'Wzór nie został znaleziony.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Wzór został przetłumaczony i zapisany. Skopiuj treść do swojego wpisu CPT za pomocą edytora bloków lub użyj go jako punktu wyjścia dla wielokrotnego bloku.','Pattern translation failed.'=>'Tłumaczenie wzorca nie powiodło się.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Pamięć podręczna tłumaczeń AI na poziomie posta, meta opisów, fragmentów i treści. Zawsze aktywna — nie wymaga osobnego przełącznika. Wpisy są automatycznie unieważniane, gdy treść lub dostawca/model AI się zmienia. Użyj przycisku "↺ Przetłumacz ponownie" na pasku narzędzi lub kliknij Wyczyść, aby wymusić nowe wywołanie API.','Permalink rules flushed successfully.'=>'Pomyślnie wyczyszczono reguły permalinków.','Permission denied.'=>'Odmowa dostępu.','Persuasive'=>'Przekonywujące','PHP constant'=>'stała PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Przypnij terminy, które nie mogą być tłumaczone lub muszą zawsze być renderowane w określony sposób (np. nazwy marek, nazwy produktów, akronimy). Ograniczenia glosariusza są wstrzykiwane do każdego żądania tłumaczenia AI dla wszystkich funkcji: tłumaczenia postów, meta opisów, fragmentów i tłumaczeń szablonów FSE.','Plain language'=>'Język prosty','Please enter some instructions first…'=>'Najpierw wprowadź instrukcje…','Please enter some text first…'=>'Najpierw wprowadź tekst…','Post'=>'Post','Post not found.'=>'Nie znaleziono wpisu.','Post Types'=>'Typy postów','Prefilled from excerpt. Edit to override.'=>'Wstępnie wypełnione z fragmentu. Edytuj, aby nadpisać.','Primary Language'=>'Główny język','Primary language'=>'Główny język','Primary language saved.'=>'Zapisano główny język.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Język główny: język, w którym napisane są Twoje istniejące treści. Wszystkie tłumaczenia są tworzone z tego języka; zmiana go nie przenosi ani nie usuwa żadnych postów.','Processing…'=>'Przetwarzanie…','Provider'=>'Dostawca','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Dostawca nie zwrócił tekstu. Sprawdź dziennik błędów WordPress, aby uzyskać szczegółowy powód awarii.','Quality'=>'Jakość','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (domyślnie — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Jakość: używana do tłumaczeń postów i generowania treści — wyższa jakość, wyższy koszt.','Quick Translate'=>'Szybkie tłumaczenie','Quick Translation'=>'Szybkie tłumaczenie','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Szybkie tłumaczenie jest używane w trybie fragmentów — krótkie fragmenty tłumaczone na żądanie z paska narzędzi, edytora lub wyskakujących okienek bloków. Używa osobnej, lżejszej konfiguracji od pełnoekranowego tłumaczenia, aby zachować szybkość i opłacalność odpowiedzi.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ponownie włącza canLockBlocks Gutenberga. Przydatne dla szablonów redakcyjnych, które muszą zapobiegać przesuwaniu lub usuwaniu określonych bloków.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ponownie włącza supportsTemplateMode. Kluczowe dla pełnych przepływów pracy edycji całej strony, gdzie celowo nadpisuje się szablony na poziomie wpisu.','Re-generates and updates the cached result.'=>'Ponownie generuje i aktualizuje zapisany wynik.','Re-scan'=>'Ponowne skanowanie','Re-scanning…'=>'Ponowne skanowanie…','Re-translate'=>'Ponowne tłumaczenie','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Przekieruj odwiedzających do ich preferowanego języka na podstawie nagłówka Accept-Language przeglądarki','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Dopracuj dalej — np. "zrób to krótsze" lub "użyj formalnego tonu"…','Refine further:'=>'Dalsza poprawa:','Refinement'=>'Dopracowywanie','Refinement failed — please try again.'=>'Nie udało się dopracować — spróbuj ponownie.','Refining…'=>'Dopracowywanie…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneruje reguły przepisywania WordPress, aby prefiksy URL, specyficzne dla języka slug i przepisywanie archiwów były zsynchronizowane. Konieczne po zmianie głównego języka lub dodaniu nowego wsparcia językowego.','Remove stored key'=>'Usuń zapisany klucz','Report an issue on GitHub'=>'Zgłoś problem na GitHubie','Request failed — please try again.'=>'Żądanie nie powiodło się — spróbuj ponownie.','Request failed.'=>'Żądanie nie powiodło się.','Request failed. Check your connection.'=>'Niepowodzenie żądania. Sprawdź połączenie.','Request failed. Please try again.'=>'Niepowodzenie żądania. Spróbuj ponownie.','Requests'=>'Żądania','Reset'=>'Resetuj','Result will appear here…'=>'Wynik pojawi się tutaj…','Retranslate'=>'Przetłumacz ponownie','Retranslating…'=>'Ponowne tłumaczenie…','Review carefully — links and slugs not updated.'=>'Dokładnie sprawdź — linki i slug nie zostały zaktualizowane.','Review translation before applying'=>'Przejrzyj tłumaczenie przed zastosowaniem','Revise'=>'Przegląd','Revision'=>'Rewizja','Revision Type'=>'Typ rewizji','Router'=>'Router','Router Tab'=>'Zakładka routera','Save Debug Setting'=>'Zapisz ustawienia debugowania','Save Router Settings'=>'Zapisz ustawienia routera','Save Settings'=>'Zapisz ustawienia','Save the post to persist changes.'=>'Zapisz wpis, aby zachować zmiany.','Save Uninstall Setting'=>'Zapisz ustawienie odinstalowania','Saved to the meta description field when you apply.'=>'Zapisano w polu meta opisu po zastosowaniu.','Scan failed: '=>'Nieudane skanowanie: ','Scan request failed. Please try again.'=>'Żądanie skanowania nie powiodło się. Spróbuj ponownie.','Scanning posts for broken language links…'=>'Skanowanie postów w poszukiwaniu uszkodzonych linków językowych…','Search'=>'Szukaj','Search Results'=>'Wyniki wyszukiwania','Security check failed — file path is not permitted.'=>'Nieudana kontrola bezpieczeństwa — ścieżka pliku jest niedozwolona.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wybierz język, aby zarządzać jego szablonami FSE, częściami szablonów i menu nawigacyjnymi.','Select language'=>'Wybierz język','SEO character-count info'=>'Informacje o liczbie znaków SEO','Server setup (subdomain)'=>'Konfiguracja serwera (subdomena)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ustawia domyślne zachowanie AI dla wszystkich funkcji w całej witrynie. Poszczególne wpisy mogą to nadpisać dla tłumaczeń i generowania treści za pomocą meta boxa Lingua Forge.','Settings'=>'Ustawienia','Settings saved.'=>'Ustawienia zapisane.','Show home link'=>'Pokaż link do strony głównej','Shown when no translation exists for the visitor\'s language.'=>'Wyświetlane, gdy nie istnieje tłumaczenie dla języka odwiedzającego.','Single'=>'Pojedynczy','Single %s'=>'Pojedynczy %s','Single: %s'=>'Pojedynczy: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Ogólny limit AI na stronie na UTC dzień (liczy zarówno tłumaczenia w Toolbar, jak i rewizje bloków). Licznik resetuje się o północy UTC. Ustaw na 0, aby wyłączyć limit.','Size'=>'Rozmiar','Some link fixes failed.'=>'Niektóre naprawy linków nie powiodły się.','Some nav ref fixes failed.'=>'Niektóre naprawy odwołań nawigacyjnych nie powiodły się.','Some part fixes failed.'=>'Niektóre naprawy części nie powiodły się.','Some parts could not be created.'=>'Niektórych części nie można utworzyć.','Some templates could not be created.'=>'Niektórych szablonów nie można utworzyć.','Some translations failed.'=>'Niektóre tłumaczenia nie powiodły się.','Source file not found.'=>'Nie znaleziono pliku źródłowego.','Source lang'=>'Język źródłowy','Source language'=>'Język źródłowy','Source term'=>'Termin źródłowy','Standard'=>'Standardowy','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard używa własnej dostrojonej temperatury dla każdej funkcji: Tłumaczenie T=0.2 (precyzyjne), Szybkie tłumaczenie T=0.4, Generator treści T=0.6 (kreatywne). Pozostałe preset\'y stosują jedną stałą temperaturę dla wszystkich funkcji.','Status'=>'Status','Status / Actions'=>'Status / Działania','Storytelling'=>'Opowiadanie','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Tryb ścisłego zachowania dla treści prawnych, regulacyjnych, medycznych lub technicznych. Gdy jest włączony, każda funkcja AI używa niskiej temperatury próbkowania i dodaje poniższy dodatek do swojego promptu systemowego — terminologia, numery artykułów, jednostki, nazwy marek i język regulacyjny są zachowywane dokładnie, a nie parafrazowane.','Structured Outline'=>'Strukturalny plan','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Tryb subdomen wymaga, aby Twój serwer internetowy kierował wszystkie subdomeny językowe (np. de.example.com) do tej instalacji WordPress. Po zmianie trybu odśwież ustawienia permalinków i wyczyść pamięć podręczną. Jeśli Twój adres URL główny zawiera www (np. www.example.com), użyj filtra lf_base_domain, aby ustawić podstawową domenę, tak aby subdomeny były poprawnie konstruowane.','Subdomain — de.example.com/'=>'Subdomena — pl.example.com/ lub de.example.com/ (w zależności od języka)','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Obsługiwani dostawcy: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Tylko jeden dostawca jest aktywny naraz. Wybierz aktywnego dostawcę na zakładce Ogólne.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, na funkcję','Target lang'=>'Język docelowy','Target Language'=>'Język docelowy','Target language'=>'Język docelowy','Target term'=>'Termin docelowy','Target: 140–160 chars for optimal SERP display'=>'Docelowo: 140–160 znaków dla optymalnego wyświetlania w SERP','Technical'=>'Techniczne','Technical / Scientific'=>'Techniczny / Naukowy','Technical / Scientific instructions'=>'Instrukcje techniczne / naukowe','Template "%s" already exists.'=>'Szablon "%s" już istnieje.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Szablon "{expected}" nie istnieje — najpierw utwórz go w Edytorze Stron.','Template has no content.'=>'Szablon nie ma treści.','Template mode'=>'Tryb szablonu','Template not found or not stored in the database.'=>'Szablon nie został znaleziony lub nie jest zapisany w bazie danych.','Template part "%s" already exists.'=>'Część szablonu "%s" już istnieje.','Template part has no content.'=>'Część szablonu nie ma treści.','Template part not found or not stored in the database.'=>'Część szablonu nie została znaleziona lub nie jest zapisana w bazie danych.','Template Parts'=>'Części szablonów','Templates'=>'Szablony','Test connection'=>'Testuj połączenie','Testing…'=>'Testowanie…','Text domain / locale'=>'Tekst domeny / lokalizacja','Text to translate'=>'Tekst do tłumaczenia','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Pamięć podręczna odpowiedzi API przechowuje surowy wynik każdego żądania AI — tłumaczenie, meta opis, fragment i generowanie treści — kluczem jest hash wejściowych danych (treść, para języków, dostawca, model). Kolejne żądania z identycznymi danymi są obsługiwane z pamięci podręcznej bez wywołania API. Pamięć podręczna różni się od Pamięci tłumaczeń: Pamięć tłumaczeń działa na poziomie bloków i jest współdzielona między postami; Pamięć odpowiedzi API działa na poziomie funkcji i jest kluczowana na poziomie posta.','The editor did not accept the content — please try again.'=>'Redaktor nie zaakceptował treści — spróbuj ponownie.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Poziom Light korzysta z szybkiego modelu skonfigurowanego w tabeli modeli powyżej (domyślnie: Haiku / Flash). Przełącz na Jakość, jeśli potrzebujesz takiej samej dokładności tłumaczenia jak w trybie pełnoekranowym dla fragmentów.','The phrase as it appears in the source text.'=>'Fraza tak jak pojawia się w tekście źródłowym.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Główny język jest zawsze dostępny na głównym adresie Twojej strony — brak prefiksu URL w trybie ścieżki, brak subdomeny językowej w trybie subdomeny. Wszystkie pozostałe języki używają albo prefiksu /lang/ (np. example.com/de/), albo subdomeny językowej (np. de.example.com), w zależności od ustawienia struktury URL poniżej.','The source page has no footnotes.'=>'Strona źródłowa nie ma przypisów.','The upload failed — please try again.'=>'Przesyłanie nie powiodło się — spróbuj ponownie.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Te przypisy pochodzą ze strony źródłowej i są wyświetlane tutaj wyłącznie w celach informacyjnych. Dodaj je do tej strony za pomocą edytora bloków.','This is the source page. Footnotes are edited directly in the block editor.'=>'To jest strona źródłowa. Przypisy są edytowane bezpośrednio w edytorze bloków.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Ten klucz jest obecnie dostarczany przez serwer %s i nie można go usunąć tutaj. Wprowadź nowy klucz powyżej, aby nadpisać go wartością z bazy danych.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Wskazówka: aby zresetować model do wbudowanego domyślnego, wyczyść pole i zapisz.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Aby użyć własnego sekretu szyfrowania (zamiast wyprowadzonej wartości wp_salt), dodaj to do wp-config.php:','Today'=>'Dziś','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Zużycie tokenów podsumowane według funkcji, dostawcy i modelu. Rejestrowane przy każdym udanym wywołaniu AI; pingi Test Connection są celowo wykluczone, aby nie zniekształcały sum. Podstawowa tabela agreguje dane dziennie — wybierz okno poniżej, aby je wyświetlić.','Tone'=>'Ton','tone'=>'ton','Tone:'=>'Ton:','Too many AI requests. Please retry in %d seconds.'=>'Zbyt wiele żądań AI. Spróbuj ponownie za %d sekund.','Total'=>'Razem','Total tokens'=>'Razem tokenów','Translate'=>'Tłumacz','Translate / Revise'=>'Tłumacz / Zrewiduj','Translate / Revise block'=>'Tłumacz / Zrewiduj blok','Translate all'=>'Przetłumacz wszystko','Translate chunk'=>'Tłumacz fragment','Translate Content'=>'Tłumacz treść','Translate missing'=>'Brak tłumaczenia','Translate page…'=>'Tłumacz stronę…','Translated content'=>'Tłumaczona treść','Translated Names'=>'Tłumaczone nazwy','Translated title'=>'Tłumaczony tytuł','Translated to:'=>'Przetłumaczono na:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Przetłumaczono. Przejrzyj w Edytorze Stron — linki wewnętrzne, adresy URL nawigacji i szablony nie są automatycznie aktualizowane.','Translating…'=>'Tłumaczenie w toku…','Translation'=>'Tłumaczenie','Translation Caching'=>'Buforowanie tłumaczeń','Translation found but permalink could not be generated'=>'Znaleziono tłumaczenie, ale nie można wygenerować odnośnika','Translation Limits'=>'Limity tłumaczeń','Translation Limits & Behavior'=>'Limity tłumaczeń i zachowanie','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Limity tłumaczeń: kontroluj, które role użytkowników mogą wywołać tłumaczenie AI, oraz ustaw miesięczny budżet tokenów. Przekroczenie budżetu wstrzymuje wywołania AI do resetu miesiąca.','Translation Memory'=>'Pamięć tłumaczeń','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Pamięć tłumaczeń buforuje wyniki AI na podstawie hasha treści, pary językowej, dostawcy i modelu. Edycja posta unieważnia wpis w pamięci podręcznej, więc następne tłumaczenie pobiera świeży wynik.','Translation Memory cleared. %d cached block was removed.'=>'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . 'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Pamięć tłumaczeń: przechowuje pełne przetłumaczone posty na podstawie hasha treści. Wyczyść ją, gdy chcesz wymusić ponowne tłumaczenie wszystkich postów, niezależnie od tego, czy ich treść się zmieniła.','Translation workflow'=>'Przepływ pracy tłumaczeń','Translation, Content Generator'=>'Tłumaczenie, Generator treści','Type'=>'Typ','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Odinstaluj zachowanie','Uninstall setting saved.'=>'Ustawienie odinstalowania zapisane.','unknown error'=>'nieznany błąd','Unknown provider.'=>'Nieznany dostawca.','Up'=>'Góra','Upload .mo file'=>'Prześlij plik .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Prześlij skompilowane pliki .mo, aby nadpisać teksty wtyczek innych firm dla określonych lokalizacji — na przykład własne tłumaczenie VikBooking, które używa "mieszkanie" zamiast "pokój". Pliki muszą mieć nazwę zgodną z konwencją WordPress: {textdomain}-{locale}.mo (np. vikbooking-ca.mo). Są przechowywane w folderze uploads i przetrwają aktualizacje wtyczek.','Upload Override'=>'Prześlij nadpisanie','URL could not be mapped to a post — check the link target exists'=>'Nie można przypisać URL do posta — sprawdź, czy cel linku istnieje','URL structure'=>'Struktura URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Struktura URL: tryb prefiksu ścieżki (example.com/de/) nie wymaga zmian na serwerze. Tryb subdomeny (de.example.com) wymaga rekordu DNS typu wildcard, certyfikatu SSL wildcard oraz zmiany konfiguracji serwera — zobacz przewodnik konfiguracji serwera.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Użyj zakładek na górze tej strony, aby skonfigurować każdą sekcję. Zmiany w zakładce Router są natychmiastowe; zmiany kluczy AI i ustawień modelu obowiązują przy następnym żądaniu AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tablica terminologii zarządzana przez użytkownika dla pary językowej. Wpisy są dodawane do promptu systemu tłumaczeń, aby AI używało preferowanych terminów konsekwentnie — kluczowe dla słownictwa dziedzinowego ("kWp", "PPA", "punkt połączenia"), nazw marek, które nie mogą być tłumaczone, oraz ustandaryzowanej frazeologii regulacyjnej. Oba pola językowe są opcjonalne: pozostaw "Język źródłowy" pusty, aby zastosować wpis niezależnie od języka, z którego tłumaczysz; pozostaw "Język docelowy" pusty, aby zastosować go do wszystkich języków docelowych naraz.','Using custom meta description.'=>'Używanie własnego meta opisu.','View'=>'Zobacz','View built-in default'=>'Wyświetl wbudowany domyślny','View details'=>'Zobacz szczegóły','View Lingua Forge details'=>'Zobacz szczegóły Lingua Forge','Visit plugin site'=>'Odwiedź stronę wtyczki','Warning:'=>'Ostrzeżenie:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Gdy włączone jest logowanie debugowania (za pomocą przełącznika poniżej lub przez zdefiniowanie LINGUAFORGE_AI_DEBUG w wp-config.php), funkcje tłumaczenia i tłumaczenia szablonów FSE zapisują swoje surowe podpowiedzi AI i odpowiedzi na dysk w celach diagnostycznych. Użyj tej sekcji, aby monitorować ten output i wyczyścić go, gdy będziesz miał to, czego potrzebujesz — pliki mogą szybko się powiększać na dużych stronach. Skonfiguruj katalog docelowy za pomocą filtra linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Po włączeniu, odwiedzający po raz pierwszy, bez pliku cookie języka i bez prefiksu języka w URL, są przekierowywani do najbliższej pasującej wersji językowej. Przekierowanie jest pomijane, jeśli preferowany język przeglądarki nie znajduje się na liście aktywnych języków routera. Po wybraniu języka przez odwiedzającego za pomocą przełącznika, plik cookie ma pierwszeństwo, a nagłówek przeglądarki jest ignorowany przy kolejnych wizytach.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Który poziom modelu użyć do tłumaczenia pełnej strony. Jakość korzysta z modelu skonfigurowanego w tabeli modeli powyżej i jest zalecana do dokładnego, długiego tłumaczenia. Przełącz na Lekki tylko wtedy, gdy priorytetem jest szybkość lub koszt, a treść jest krótka.','WP-CLI reference'=>'Odwołanie do WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Zapisuj podpowiedzi i odpowiedzi AI na dysk w celach diagnostycznych','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Możesz również definiować klucze jako stałe lub zmienne środowiskowe (np. w wp-config.php). Te źródła są automatycznie używane jako zapasowe, gdy nie ma zapisanej klucza w bazie danych.','You do not have permission to manage these settings.'=>'Nie masz uprawnień do zarządzania tymi ustawieniami.','You do not have permission to read this post.'=>'Nie masz uprawnień do odczytu tego wpisu.','{n} stale path(s)'=>'{n} nieaktualna(e) ścieżka(e)','— Any source language —'=>'— Dowolny język źródłowy —','— Any target language —'=>'— Dowolny język docelowy —','— Any target —'=>'— Dowolny język docelowy —','— Any —'=>'— Dowolny —','— auto-detect —'=>'— automatyczne wykrywanie —','— select a language —'=>'— wybierz język —','— toggle in Settings → Behavior.'=>'— przełącznik w Ustawienia → Zachowanie.','← Back'=>'← Wstecz','↑ Detected from current post'=>'↑ Wykryto z obecnego wpisu','↺ Re-translate'=>'↺ Ponowne tłumaczenie','↺ Refine'=>'↺ Ulepszanie','↺ Refresh'=>'↺ Odśwież','↺ Refreshing…'=>'↺ Odświeżanie…','⚠ Borderline'=>'⚠ Granica','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Nie znaleziono postów <strong>{lang}</strong>. Upewnij się, że wszystkie przetłumaczone posty mają ustawiony meta języka na <strong>{lang}</strong> w metaboxie języka.','⚠ No changes'=>'⚠ Brak zmian','⚠ No changes — re-scan?'=>'⚠ Brak zmian — ponowne skanowanie?','✅ Fixed ({n})'=>'✅ Naprawiono ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Nie znaleziono uszkodzonych linków ani niezgodności szablonów dla <strong>{lang}</strong>. Skanowano <strong>{scanned}</strong> postów i stron — wszystkie kontrole przeszły pomyślnie. Linki do części szablonów (nagłówek, stopka, pasek boczny) nie są tutaj uwzględnione — użyj przycisku Napraw części szablonów, aby sprawdzić je osobno.','✅ Template fixed'=>'✅ Szablon naprawiony','✓ All parts created.'=>'✓ Wszystkie części utworzone.','✓ All templates created.'=>'✓ Wszystkie szablony utworzone.','✓ All translated.'=>'✓ Wszystko przetłumaczone.','✓ Configured'=>'✓ Skonfigurowano','✓ Connection OK'=>'✓ Połączenie OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Treść wygenerowana — zobacz nakładkę, aby przejrzeć, dopracować i zastosować.','✓ Done'=>'✓ Zrobione','✓ Enabled'=>'✓ Włączone','✓ Good length'=>'✓ Odpowiednia długość','✓ In safe storage'=>'✓ W bezpiecznej pamięci','✓ Language installed.'=>'✓ Język zainstalowany.','✓ Links fixed.'=>'✓ Linki naprawione.','✓ Nav refs fixed.'=>'✓ Naprawione odwołania nawigacyjne.','✓ Parts fixed.'=>'✓ Części naprawione.','✓ Pattern translated.'=>'✓ Wzorzec przetłumaczony.','✓ Refined — review the updated draft above.'=>'✓ Dopracowano — przejrzyj zaktualizowany szkic powyżej.','✓ Translation saved'=>'✓ Tłumaczenie zapisane','✗ Disabled'=>'✗ Wyłączone','✗ Error:'=>'✗ Błąd:','✗ Failed:'=>'✗ Niepowodzenie:','✗ Not configured'=>'✗ Nie skonfigurowano','✗ Too long'=>'✗ Za długo','✗ Too short'=>'✗ Za krótko','❌ Failed'=>'❌ Niepowodzenie','📄 Wrong template'=>'📄 Zły szablon','📍 Stale path (page moved)'=>'📍 Nieaktualna ścieżka (strona przeniesiona)']];
